import { Button, Chevron } from "march/ui"
import { gift } from "march/icons"

// sürpriz kutusu: düğme yalnız aria-expanded taşır; ok onu kendiliğinden izler (open verilmedi) ve yaylı döner
export function GiftBox() {
  let $open = false
  return <div sx={{ flex: "col", gap: 2 }}>
    <Button variant="ghost" icon={gift} aria-expanded={$open ? "true" : "false"} on:click={() => $open = !$open}>
      {$open ? "Kutuyu kapat" : "Sürprizi aç"} <Chevron direction="down" motion="spring" size="md" m:color="brand-pink" />
    </Button>
    {$open ? <p sx={{ text: "lg" }}>🎉 Ok tek satır bağlama kodu istemedi: düğmenin durumunu kendisi okudu.</p> : null}
  </div>
}

import { Card, Button, Chevron } from "march/ui"

// bir kulübün sık sorulan soruları: her başlık düğmesi aria-expanded taşır, ok onu izler, cevap yalnız açıkken görünür
const faqs = [
  { q: "Üyelik ücretli mi?", a: "Hayır. Koşulara katılmak ücretsiz; yalnızca yarış kayıtları ücretlidir." },
  { q: "Hangi günler koşuyoruz?", a: "Salı ve perşembe 19.00'da, cumartesi 09.00'da Moda sahilinde." },
  { q: "Yeni başlayanlar katılabilir mi?", a: "Elbette. Her koşuda tempoyu düşük tutan bir rehber grup var." },
]

// tek bir soru: kendi açık / kapalı durumu var
const Faq = (props: { q: string; a: string }) => {
  let $open = false
  return <div sx={{ flex: "col", gap: 1 }}>
    <Button variant="ghost" block aria-expanded={$open ? "true" : "false"} on:click={() => $open = !$open}>
      <span sx={{ flex: ["row", "between"], w: "full" }}>{props.q} <Chevron direction="down" /></span>
    </Button>
    {$open ? <p sx={{ px: 3, color: "muted" }}>{props.a}</p> : null}
  </div>
}

export function FaqList() {
  return <Card title="Sık sorulanlar">
    <div sx={{ flex: "col", gap: 1 }}>{faqs.map((f) => <Faq q={f.q} a={f.a} />)}</div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { ChevronLab } from "./ChevronLab.tsx"

// ChevronLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Hepsini aç'a basınca oklar kapalıdan açığa geçer", async () => {
  const s = renderTest(() => <ChevronLab />)
  expect(s.get(".lab-dir-end")?.classList.contains("is-closed")).toBe(true)
  await s.click("Hepsini aç")
  expect(s.get(".lab-dir-end")?.classList.contains("is-open")).toBe(true)
  expect(s.find("Hepsini kapat")).not.toBe(null)
})

test("open verilmeyen ok kendiliğinden (is-auto) ve süs olarak gizli", () => {
  const s = renderTest(() => <ChevronLab />)
  const auto = s.get(".lab-auto")
  expect(auto?.classList.contains("is-auto")).toBe(true)
  expect(auto?.getAttribute("aria-hidden")).toBe("true")
  expect(s.get(".lab-dir-up")?.classList.contains("m-chevron-up")).toBe(true)
})

test("motion={false} sıçrar; kendi ikonu ve metin işareti çizilir", () => {
  const s = renderTest(() => <ChevronLab />)
  expect(s.get(".lab-still")?.classList.contains("is-still")).toBe(true)
  expect(s.get(".lab-text")?.textContent).toBe("›")
  expect(s.get(".lab-own svg")).not.toBe(null)
  expect(s.get(".lab-own")?.getAttribute("data-m-color")).toBe("primary")
})

test("Yaprak yap: kutu kalır, ok çizilmez; data-* öznitelik oktadır", async () => {
  const s = renderTest(() => <ChevronLab />)
  expect(s.get(".lab-leaf")?.getAttribute("data-node")).toBe("kok")
  await s.click("Yaprak yap")
  expect(s.get(".lab-leaf")?.classList.contains("is-leaf")).toBe(true)
  expect(s.get(".lab-leaf svg")).toBe(null)
})
